-- ==========================================================================
-- Object      : SEC.MP_CUSTOMER_ADDRESS (masking policy)
-- Generated by: SemLift 1.0.0
-- Rules       : SEC-03
-- Confidence  : 1.00 (proposed)
-- Governance  : owner=Energy Data Engineering Team; classification=Restricted
-- ==========================================================================
CREATE MASKING POLICY IF NOT EXISTS SEC.MP_CUSTOMER_ADDRESS AS (v STRING) RETURNS STRING -> v
  COMMENT = 'Full street address masked for non-billing roles (show City/Region only).';

ALTER MASKING POLICY SEC.MP_CUSTOMER_ADDRESS SET BODY ->
    CASE
    WHEN CONTAINS(',' || COALESCE(SYSTEM$GET_TAG_ON_CURRENT_COLUMN('GOV.ABAC_POLICY'), '') || ',', ',REGULATORY_SENSITIVE_DATA,') AND NOT (IS_ROLE_IN_SESSION('COMPLIANCE_OFFICERS') OR IS_ROLE_IN_SESSION('NERC_AUDITORS') OR IS_ROLE_IN_SESSION('REPORT_ADMINS')) THEN '[Address Restricted]'
    WHEN CONTAINS(',' || COALESCE(SYSTEM$GET_TAG_ON_CURRENT_COLUMN('GOV.ABAC_POLICY'), '') || ',', ',SENSITIVE_DATA_POLICY,') AND COALESCE((SELECT MAX(a.ATTRIBUTE_VALUE) FROM SEC.MAP_USER_ATTRIBUTE a WHERE a.USERNAME = CURRENT_USER() AND a.ATTRIBUTE_NAME = 'dataClassification'), '') = 'restricted' THEN '[Address Restricted]'
    WHEN CONTAINS(',' || COALESCE(SYSTEM$GET_TAG_ON_CURRENT_COLUMN('GOV.ABAC_POLICY'), '') || ',', ',SENSITIVE_FINANCIAL_DATA,') AND (COALESCE((SELECT MAX(a.ATTRIBUTE_VALUE) FROM SEC.MAP_USER_ATTRIBUTE a WHERE a.USERNAME = CURRENT_USER() AND a.ATTRIBUTE_NAME = 'dataClassification'), '') <> 'restricted' AND COALESCE((SELECT MAX(a.ATTRIBUTE_VALUE) FROM SEC.MAP_USER_ATTRIBUTE a WHERE a.USERNAME = CURRENT_USER() AND a.ATTRIBUTE_NAME = 'dataClassification'), '') <> 'confidential') THEN '[Address Restricted]'
    WHEN IS_ROLE_IN_SESSION('COMPLIANCE_OFFICERS') OR IS_ROLE_IN_SESSION('FINANCE_ANALYSTS') OR IS_ROLE_IN_SESSION('OPERATIONS_VIEWERS') THEN '[Address Restricted]'
    WHEN IS_ROLE_IN_SESSION('BILLING_ANALYSTS') OR IS_ROLE_IN_SESSION('FIELD_TECHNICIANS') OR IS_ROLE_IN_SESSION('REPORT_ADMINS') THEN v
    ELSE '[Address Restricted]'
    END;

ALTER MASKING POLICY SEC.MP_CUSTOMER_ADDRESS SET COMMENT = 'Full street address masked for non-billing roles (show City/Region only).';
